import { DataGrid, type DataGridRowsRequest } from '@absoluteui/components/data-grid';

interface Ticket {
  id: string;
  subject: string;
  priority: number;
}

// Stands in for your API: 100,000 tickets, sorted on the "server", answered after 150 ms.
const total = 100_000;
function getRows(request: DataGridRowsRequest, signal: AbortSignal): Promise<{ rows: Ticket[]; rowCount: number }> {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      const descending = request.sort[0]?.column === 'id' && request.sort[0].direction === 'descending';
      const rows = Array.from({ length: Math.max(0, Math.min(request.end, total) - request.start) }, (_, k) => {
        const n = descending ? total - 1 - (request.start + k) : request.start + k;
        return { id: `T-${String(n)}`, subject: `Ticket ${String(n)}`, priority: (n % 5) + 1 };
      });
      resolve({ rows, rowCount: total });
    }, 150);
    // The grid aborts requests it no longer needs.
    signal.addEventListener('abort', () => {
      clearTimeout(timer);
      reject(signal.reason);
    });
  });
}

