import { DataGrid } from '@absoluteui/components/data-grid';
import { columnChooser, columnMenu, contextMenu, find, notes, sideBar, statusBar, toolbar, tooltips, type DataGridNote } from '@absoluteui/components/data-grid/accessories';

interface Employee {
  id: string;
  name: string;
  department: string;
  salary: number;
}

const rows: Employee[] = Array.from({ length: 60 }, (_, i) => ({ id: String(i), name: `Employee ${String(i + 1)}`, department: ['Sales', 'Finance', 'Support'][i % 3] ?? 'Sales', salary: 40_000 + ((i * 731) % 30_000) }));
// Notes live in your application (here in memory); the grid stores nothing.
const saved = new Map<string, DataGridNote>([['3|salary', { text: 'Raise pending', author: 'HR' }]]);
const chooser = columnChooser<Employee>();
const host = document.createElement('div');
host.style.setProperty('block-size', '460px');
document.body.append(host);
DataGrid.create<Employee>(host, {
  label: 'Staff',
  rows,
  rowId: (r) => r.id,
  cellSelection: true,
  accessories: [
    columnMenu(), // a menu button in each header, Shift+F10 on a header
    contextMenu(), // right-click or Shift+F10 on a cell
    chooser,
    sideBar({ panels: ['columns', 'filters'] }),
    statusBar(),
    toolbar({ items: ['chooser', 'resetColumns', 'separator', { id: 'hello', label: 'Say hello', action: () => console.log('hello') }] }),
    find(),
    tooltips(),
    notes({
      store: {
        get: (rowId, column) => Promise.resolve(saved.get(`${rowId}|${column}`) ?? null),
        set: (rowId, column, note) => {
          if (note) saved.set(`${rowId}|${column}`, note);
          else saved.delete(`${rowId}|${column}`);
          return Promise.resolve();
        },
        index: () => Promise.resolve([...saved.keys()].map((k) => ({ rowId: k.split('|')[0] ?? '', column: k.split('|')[1] ?? '' }))),
      },
      author: 'Me',
    }),
  ],
  columns: [
    { id: 'name', header: 'Name', field: 'name', filter: 'text', tooltip: true },
    { id: 'department', header: 'Department', field: 'department', filter: 'set', groupable: true },
    { id: 'salary', header: 'Salary', field: 'salary', type: 'currency', currency: 'EUR', filter: 'number' },
  ],
});

