import { parseCsv } from '@absoluteui/helpers/csv';
import { coerceCsvValues, DataGrid, inferColumns } from '@absoluteui/components/data-grid';

type Row = Record<string, string | number | boolean | null>;

const text = 'name,region,amount\nAda,North,120\nBen,South,95\nCy,North,60\n';
let rows: Row[] = coerceCsvValues(parseCsv(text, { header: true }).rows).map((r, i) => ({ ...r, id: String(i) }));

function host(height: string): HTMLElement {
  const el = document.createElement('div');
  el.style.setProperty('block-size', height);
  document.body.append(el);
  return el;
}

// Columns generated from the rows' keys and value types.
const main = DataGrid.create<Row>(host('220px'), {
  label: 'Sales',
  rows,
  rowId: (r) => String(r.id),
  columns: inferColumns(rows, { exclude: ['id'] }),
  // Drop a .csv file on the grid to load it (offer a file input too: dropping needs a pointer).
  fileDrop: {
    accept: ['.csv', 'text/csv'],
    onFiles: (files) => {
      void files[0]?.text().then((csv) => {
        rows = coerceCsvValues(parseCsv(csv, { header: true }).rows).map((r, i) => ({ ...r, id: String(i) }));
        main.update({ rows, columns: inferColumns(rows, { exclude: ['id'] }) });
      });
    },
  },
});
// A totals grid that keeps the same columns and horizontal scroll.
const totals = DataGrid.create<Row>(host('90px'), {
  label: 'Totals',
  rows: [{ id: 'total', name: 'Total', region: null, amount: rows.reduce((sum, r) => sum + (typeof r.amount === 'number' ? r.amount : 0), 0) }],
  rowId: (r) => String(r.id),
  columns: inferColumns(rows, { exclude: ['id'] }),
});
main.alignWith(totals);
